const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const center = ee.Geometry.Point([-118.53, 34.05]); // Pacific Palisades approx center
  const region = center.buffer(10000); // 10 km buffer
  const scale = 3000;

  const days = [
    { label: '2025-01-09', start: '2025-01-09', end: '2025-01-10' },
    { label: '2025-01-12', start: '2025-01-12', end: '2025-01-13' },
  ];

  async function getDayStats(day) {
    const primaryId = 'COPERNICUS/S5P/OFFL/L3_NO2';
    const fallbackId = 'COPERNICUS/S5P/NRTI/L3_NO2';

    let usedId = primaryId;
    let col = ee.ImageCollection(usedId).filterDate(day.start, day.end);
    let primarySize = await col.size().getInfo();

    let size = primarySize;
    if (size === 0) {
      usedId = fallbackId;
      col = ee.ImageCollection(usedId).filterDate(day.start, day.end);
      size = await col.size().getInfo();

      if (size === 0) {
        // Widen to ±1 day window
        const d0 = ee.Date(day.start);
        const start2 = d0.advance(-1, 'day');
        const end2 = d0.advance(2, 'day');

        usedId = primaryId;
        col = ee.ImageCollection(usedId).filterDate(start2, end2);
        size = await col.size().getInfo();

        if (size === 0) {
          usedId = fallbackId;
          col = ee.ImageCollection(usedId).filterDate(start2, end2);
          size = await col.size().getInfo();

          if (size === 0) {
            return { status: 'C1', primarySize, usedId: null, usedSize: 0 };
          }
        }
      }
    }

    // Build a single image (mean of collection) and apply QA mask
    let img = col.select(['tropospheric_NO2_column_number_density', 'qa_value']).mean();
    img = img.updateMask(img.select('qa_value').gte(0.75));

    // Count valid and total pixels
    const band = 'tropospheric_NO2_column_number_density';
    const validCount = await img.select(band).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9,
    }).get(band).getInfo();

    const totalCount = await ee.Image(1).rename('c').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9,
    }).get('c').getInfo();

    if (!totalCount || totalCount === 0) {
      return { status: 'C3', primarySize, usedId, usedSize: size, valid: validCount || 0, total: totalCount || 0, mean: null };
    }

    if (!validCount || validCount === 0) {
      return { status: 'C2', primarySize, usedId, usedSize: size, valid: 0, total: totalCount, mean: null };
    }

    const meanVal = await img.select(band).reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9,
    }).get(band).getInfo();

    if (meanVal === null || isNaN(meanVal) || meanVal < 0 || meanVal > 0.05) {
      return { status: 'C3', primarySize, usedId, usedSize: size, valid: validCount, total: totalCount, mean: meanVal };
    }

    return { status: 'ok', primarySize, usedId, usedSize: size, valid: validCount, total: totalCount, mean: meanVal };
  }

  try {
    const s1 = await getDayStats(days[0]);
    const s2 = await getDayStats(days[1]);

    console.log(`Region: Pacific Palisades center (-118.53, 34.05), buffer 10km`);
    console.log(`OFFL Images 2025-01-09: ${s1.primarySize !== undefined ? s1.primarySize : 'NA'}`);
    console.log(`OFFL Images 2025-01-12: ${s2.primarySize !== undefined ? s2.primarySize : 'NA'}`);

    if (s1.status === 'C1' || s2.status === 'C1') {
      console.log(`Data gap after fallback/widening.`);
      console.log('C1');
      return;
    }
    if (s1.status === 'C2' || s2.status === 'C2') {
      console.log(`No valid pixels after QA masking.`);
      console.log('C2');
      return;
    }
    if (s1.status === 'C3' || s2.status === 'C3') {
      console.log(`Calculation failure or invalid values.`);
      console.log('C3');
      return;
    }

    console.log(`Used collections: ${s1.usedId.split('/').pop()} (d1 n=${s1.usedSize}), ${s2.usedId.split('/').pop()} (d2 n=${s2.usedSize})`);

    const validPct1 = (100 * s1.valid / s1.total);
    const validPct2 = (100 * s2.valid / s2.total);
    console.log(`2025-01-09 NO2 mean: ${s1.mean.toExponential(3)} mol/m^2 | Valid px: ${s1.valid}/${s1.total} (${validPct1.toFixed(1)}% valid)`);
    console.log(`2025-01-12 NO2 mean: ${s2.mean.toExponential(3)} mol/m^2 | Valid px: ${s2.valid}/${s2.total} (${validPct2.toFixed(1)}% valid)`);

    if (s1.mean > s2.mean) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
